DELETE FROM public.herb_pubmed_monographs d WHERE d.slug IN ('triphala-digestive', 'triphala-formula', 'triphala-indian') AND EXISTS (SELECT 1 FROM public.herb_pubmed_monographs k WHERE k.slug = 'triphala');
